/** Both native row variants share one real paint setter. Their own layout,
 * clipping, palette selection and business admission remain in the Builder. */
class ReaderDirectoryRowBackgroundModifier implements AttributeModifier<RowAttribute> {
  private readonly color: ResourceColor;
  constructor(color: ResourceColor) { this.color = color; }
  applyNormalAttribute(instance: RowAttribute): void { instance.backgroundColor(this.color); }
}
